import { Component, effect, input } from '@angular/core';
import { CoreIcon, ICON_TEMPLATE } from '@primeicons/angular/core';
import { ICON_LOADERS } from '@primeicons/core/loaders';

@Component({
    selector: 'svg[pIcon]',
    standalone: true,
    template: ICON_TEMPLATE
})
export class PIcon extends CoreIcon {
    pIcon = input<string | undefined | null>(undefined);

    constructor() {
        super();
        effect(async () => {
            const name = this.pIcon();

            if (!name) {
                this._icon = null;

                return;
            }

            const loader = ICON_LOADERS[name];

            if (!loader) {
                console.warn(`[PIcon] Unknown icon: "${name}"`);
                this._icon = null;

                return;
            }

            try {
                this._icon = await loader();
            } catch (e) {
                console.error(`[PIcon] Failed to load icon "${name}":`, e);
                this._icon = null;
            }
        });
    }
}
